import { useCallback, useMemo, useRef } from 'react';
import type { NodeType, NodeId } from '@hierarchidb/common-types';
import { getWorkerBridge } from '@hierarchidb/ui-worker-client';
import { notify } from '@hierarchidb/components';
import { getWorkerClientHook, type WorkerClientRef } from '@hierarchidb/ui-worker-provider';
import type { BuildStatus } from '@hierarchidb/components';
import type { ShapeEntity } from '../../../common/types/index.js';
import { normalizeDataSourceName } from '../../../services/utils/utils.js';

type Args = {
  nodeType: NodeType;
  nodeId?: NodeId;
  sessionId?: string | null;
  data?: Partial<ShapeEntity>;
  onChange: (patch: Partial<ShapeEntity>) => void;
  buildStatus: BuildStatus;
};

export const useBatchSessionActions = ({
  nodeType,
  nodeId,
  sessionId,
  data,
  onChange,
  buildStatus,
}: Args) => {
  const debugScope = '[ShapeBuildProgressStep]';
  const bridgeRef = useRef(getWorkerBridge());
  const workerClientHook = useMemo(() => {
    try {
      return getWorkerClientHook<WorkerClientRef | null>();
    } catch {
      return null;
    }
  }, []);
  const workerClient = workerClientHook ? workerClientHook() : null;

  const saveDraftBeforeBatch = useCallback(async (patch?: Partial<ShapeEntity>) => {
    console.debug(`${debugScope} saveDraftBeforeBatch:start`, {
      nodeId,
      hasWorkerClient: Boolean(workerClient),
      buildStatus,
      sessionId,
    });
    if (!nodeId) {
      console.debug(`${debugScope} saveDraftBeforeBatch:missingNodeId`);
      notify.warning('NodeId is missing.');
      return false;
    }
    if (!workerClient) {
      console.debug(`${debugScope} saveDraftBeforeBatch:missingWorkerClient`);
      notify.error('Worker client is unavailable.');
      return false;
    }
    let nextUrlMetadata = data?.urlMetadata;
    if (!nextUrlMetadata || nextUrlMetadata.length === 0) {
      console.debug(`${debugScope} saveDraftBeforeBatch:missingUrlMetadata`, {
        dataSource: normalizeDataSourceName(data?.batchConfig?.dataSource ?? data?.dataSourceName),
      });
      notify.warning('URL metadata is missing. Please review the selection step.');
      return false;
    }
    const resolvedUrlMetadata = nextUrlMetadata;
    try {
      console.debug(`${debugScope} saveDraftBeforeBatch:updateDraft`, {
        nodeId,
        urlMetadataCount: resolvedUrlMetadata.length,
      });
      const api = workerClient.getAPI();
      const updater = await api.getTreeNodeUpdaterAPI();
      await updater.updateTreeNode(nodeId, {
        mode: 'save-draft',
        draftData: {
          ...(data ?? {}),
          ...(patch ?? {}),
          urlMetadata: resolvedUrlMetadata,
        } as Record<string, unknown>,
      });
      console.debug(`${debugScope} saveDraftBeforeBatch:complete`, {
        nodeId,
        urlMetadataCount: resolvedUrlMetadata.length,
      });
      return true;
    } catch (error) {
      notify.error('Failed to save draft.');
      console.error('[ShapeBuildProgressStep] save draft failed', error);
      return false;
    }
  }, [data, nodeId, workerClient]);

  const persistDraftPatch = useCallback(async (patch: Partial<ShapeEntity>) => {
    if (!nodeId || !workerClient) return;
    try {
      const api = workerClient.getAPI();
      const updater = await api.getTreeNodeUpdaterAPI();
      await updater.updateTreeNode(nodeId, {
        mode: 'save-draft',
        draftData: {
          ...(data ?? {}),
          ...patch,
        } as Record<string, unknown>,
      });
      onChange(patch);
    } catch (error) {
      console.error('[ShapeBuildProgressStep] failed to persist build markers', error);
    }
  }, [data, nodeId, onChange, workerClient]);

  const handleStartOrResume = useCallback(async (): Promise<boolean> => {
    console.debug(`${debugScope} startOrResume:click`, {
      nodeId,
      buildStatus,
      sessionId,
    });
    if (!nodeId) {
      notify.warning('NodeId is missing.');
      return false;
    }
    const saved = await saveDraftBeforeBatch();
    if (!saved) {
      console.debug(`${debugScope} startOrResume:saveDraftFailed`);
      return false;
    }
    try {
      await bridgeRef.current.initialize();
      console.debug(`${debugScope} startOrResume:bridgeReady`);
      if (buildStatus === 'paused' && sessionId) {
        console.debug(`${debugScope} startOrResume:resume`, { sessionId });
        try {
          await bridgeRef.current.resumeBatchSession(nodeType, sessionId);
          console.debug(`${debugScope} startOrResume:resumeOk`, { sessionId });
          await persistDraftPatch({ processingStatus: 'processing' });
          return true;
        } catch (error) {
          const message = error instanceof Error ? error.message : String(error);
          if (!/session .*not found/i.test(message)) {
            throw error;
          }
          console.debug(`${debugScope} startOrResume:resumeNotFound`, { sessionId });
          await persistDraftPatch({ batchSessionId: undefined });
        }
      }
      console.debug(`${debugScope} startOrResume:startBatch`, { nodeId, nodeType });
      const statusResult = await bridgeRef.current.startBatchSession(nodeType, nodeId);
      console.debug(`${debugScope} startOrResume:startBatchResult`, statusResult ?? null);
      if (statusResult?.sessionId) {
        const nextStatus = statusResult.status === 'paused'
          ? 'paused'
          : statusResult.status === 'completed'
            ? 'completed'
            : statusResult.status === 'failed'
              ? 'failed'
              : 'processing';
        await persistDraftPatch({ batchSessionId: statusResult.sessionId, processingStatus: nextStatus });
      } else {
        await persistDraftPatch({ processingStatus: 'processing' });
      }
      return true;
    } catch (error) {
      notify.error('Failed to start or resume build.');
      console.error('[ShapeBuildProgressStep] start/resume failed', error);
      return false;
    }
  }, [buildStatus, nodeId, nodeType, persistDraftPatch, saveDraftBeforeBatch, sessionId]);

  const handlePause = useCallback(async () => {
    console.debug(`${debugScope} pause:click`, { sessionId, nodeType });
    if (!sessionId) {
      notify.warning('SessionId is missing.');
      return;
    }
    const saved = await saveDraftBeforeBatch();
    if (!saved) {
      console.debug(`${debugScope} pause:saveDraftFailed`, { sessionId });
      return;
    }
    try {
      await bridgeRef.current.initialize();
      console.debug(`${debugScope} pause:bridgeReady`, { sessionId });
      await bridgeRef.current.pauseBatchSession(nodeType, sessionId);
      console.debug(`${debugScope} pause:ok`, { sessionId });
      await persistDraftPatch({ processingStatus: 'paused' });
    } catch (error) {
      notify.error('Failed to pause build.');
      console.error('[ShapeBuildProgressStep] pause failed', error);
    }
  }, [nodeType, saveDraftBeforeBatch, sessionId]);

  return {
    handleStartOrResume,
    handlePause,
  };
};
