import { useMemo } from 'react';
import type { BuildStatus } from '@hierarchidb/components';
import type { ShapeProgressStatus } from '../useShapeProgress.js';
import { useTranslation } from '../../i18n.js';

type Options = {
  forcePaused?: boolean;
};

export const useBuildStatus = (
  status: ShapeProgressStatus | null,
  options: Options = {},
): { buildStatus: BuildStatus; statusLabel: string; effectiveStatus: ShapeProgressStatus | null } => {
  const { t } = useTranslation();
  const effectiveStatus = useMemo(() => {
    if (!status) return status;
    if (options.forcePaused && status.status === 'processing') {
      return { ...status, status: 'paused' as const };
    }
    return status;
  }, [options.forcePaused, status]);

  const buildStatus: BuildStatus = useMemo(() => {
    switch (effectiveStatus?.status) {
      case 'idle':
        return 'idle';
      case 'processing':
        return 'running';
      case 'paused':
        return 'paused';
      case 'failed':
      case 'cancelled':
        return 'failed';
      case 'completed':
        return 'completed';
      default:
        return 'idle';
    }
  }, [effectiveStatus]);

  const statusLabel = useMemo(() => {
    switch (effectiveStatus?.status) {
      case 'idle':
        return t('build.status.ready', 'Ready to start build');
      case 'processing':
        return t('build.status.running', 'Build in progress');
      case 'paused':
        return t('build.status.paused', 'Build paused');
      case 'completed':
        return t('build.status.completed', 'Build completed');
      case 'failed':
        return t('build.status.failed', 'Build failed');
      case 'cancelled':
        return t('build.status.cancelled', 'Build cancelled');
      default:
        return t('build.status.ready', 'Ready to start build');
    }
  }, [effectiveStatus, t]);

  return { buildStatus, statusLabel, effectiveStatus };
};
